<?php
if (!defined('ABSPATH')) exit;
/** Read-only persistence indicators, not a malware verdict. */
final class WPSX_Persistence {
 const OPT='wpsx_persistence_findings';
 static function init(){add_action('admin_menu',[__CLASS__,'menu'],35);add_action('admin_post_wpsx_persistence_scan',[__CLASS__,'scan']);}
 static function menu(){add_submenu_page('wpsx','Persistence Audit','Persistence Audit','manage_options','wpsx_persistence',[__CLASS__,'page']);}
 static function add(&$rows,$category,$detail,$severity='review'){$rows[]=['category'=>$category,'detail'=>$detail,'severity'=>$severity];}
 static function scan(){if(!current_user_can('manage_options'))wp_die('Forbidden');check_admin_referer('wpsx_persistence_scan');$rows=[];
  foreach(['users_can_register','default_role','active_plugins'] as $name){$v=get_option($name);if($name==='users_can_register' && $v)self::add($rows,'Registration','Public registration enabled; verify default role');if($name==='default_role' && in_array($v,['administrator','editor'],true))self::add($rows,'Registration','Elevated default role: '.$v,'high');}
  foreach(get_users(['role'=>'administrator','fields'=>['ID','user_login','user_registered']]) as $user)self::add($rows,'Administrator','Account ID '.(int)$user->ID.' / '.sanitize_user($user->user_login).' / created '.sanitize_text_field($user->user_registered));
  foreach(['wp-content/mu-plugins','wp-content/uploads','wp-content/upgrade'] as $dir){$full=ABSPATH.$dir;if(!is_dir($full))continue;$it=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($full,FilesystemIterator::SKIP_DOTS));$count=0;foreach($it as $file){if(++$count>15000){self::add($rows,'Coverage','Limit reached in '.$dir);break;}if(!$file->isFile()||$file->isLink())continue;$rel=str_replace('\\','/',substr($file->getPathname(),strlen(ABSPATH)));if(preg_match('/\.(?:php[0-9]?|phtml|phar)$/i',$rel)){if(preg_match('~/(?:uploads|upgrade)/~',$rel) && basename($rel)==='index.php' && $file->getSize()<2048){$body=@file_get_contents($file->getPathname());if(is_string($body)&&preg_match('/^\s*<\?php\s*(?:(?:\/\/|#)[^\r\n]*|\/\*.*?\*\/|\s)*\s*(?:\?>)?\s*$/s',$body))continue;}self::add($rows,'PHP in writable or must-use folder',$rel,'high');}}}
  foreach(['.user.ini','wp-config.php','wp-content/advanced-cache.php','wp-content/object-cache.php','wp-content/db.php','wp-content/sunrise.php'] as $rel){if(is_file(ABSPATH.$rel))self::add($rows,'Bootstrap / configuration','Present: '.$rel);}
  if(function_exists('_get_cron_array')){foreach((array)_get_cron_array() as $timestamp=>$hooks){foreach((array)$hooks as $hook=>$events){if(preg_match('/(?:eval|shell|base64|inject|remote_exec)/i',$hook))self::add($rows,'Scheduled task','Suspicious hook name: '.sanitize_text_field($hook),'high');}}}
  update_option(self::OPT,['time'=>time(),'rows'=>array_slice($rows,0,1000)],false);wp_safe_redirect(admin_url('admin.php?page=wpsx_persistence'));exit;
 }
 static function page(){if(!current_user_can('manage_options'))return;$data=get_option(self::OPT,[]);$rows=$data['rows']??[];echo '<div class="wrap"><h1>Sentinel X — Persistence Audit</h1><p>Read-only indicators. An administrator account, must-use plugin, or drop-in may be legitimate. Review before changing anything. This scan does not inspect all database content or establish who changed a file.</p><form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="wpsx_persistence_scan">';wp_nonce_field('wpsx_persistence_scan');submit_button('Run persistence audit');echo '</form><p>Last run: '.(!empty($data['time'])?esc_html(wp_date('Y-m-d H:i:s',$data['time'])):'Never').'</p><table class="widefat striped"><thead><tr><th>Priority</th><th>Category</th><th>Detail</th></tr></thead><tbody>';foreach($rows as $r)echo '<tr><td>'.esc_html($r['severity']).'</td><td>'.esc_html($r['category']).'</td><td>'.esc_html($r['detail']).'</td></tr>';echo '</tbody></table></div>';}
}
